contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to withdraw pending flash governance assets for a given target and asset.
    // Inputs:
    // - targetContract: the target for which the decision was made
    // - asset: the ERC20 asset address configured in flashGovernanceConfig.asset
    // We cannot call functions that require onlySuccessfulProposal here because the test
    // environment creates a fresh C with default DAO; we only exercise withdrawGovernanceAsset.
    function run(address targetContract, address asset) public payable {
        require(targetContract != address(0) && asset != address(0), "nonzero");

        // Read the pending config for (targetContract, address(this)) before calling
        (address pre_asset, uint256 pre_amount, uint256 pre_unlockTime, , ) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        // Call withdrawGovernanceAsset and catch revert
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read the pending entry again
        (address post_asset, uint256 post_amount, uint256 post_unlockTime, , ) = c.pendingFlashDecision(targetContract, address(this));

        // If the call succeeded (did not revert), then preconditions must have matched the require in C:
        //   pre_asset == asset
        //   pre_amount > 0
        //   pre_unlockTime < block.timestamp
        // And the effect must be that the pending entry was deleted (post_amount == 0 and post_asset == address(0)).
        // If the call reverted, then at least one of the preconditions was not satisfied.
        assert(
            (!reverted && pre_asset == asset && pre_amount > 0 && pre_unlockTime < block.timestamp && post_amount == 0) ||
            (reverted && (pre_asset != asset || pre_amount == 0 || !(pre_unlockTime < block.timestamp)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test calling withdrawGovernanceAsset for (targetContract, asset).
    // If the call succeeds, then before-call pending entry must have matched the require in C
    // and after-call the pending amount must be zero (entry cleared) and C no longer hold that pending amount.
    function run(address targetContract, address asset) public payable {
        require(targetContract != address(0) && asset != address(0));

        // Read the pending entry for this contract (msg.sender will be this test contract when calling c)
        (address pre_asset, uint256 pre_amount, uint256 pre_unlockTime, , ) = c.pendingFlashDecision(targetContract, address(this));

        // Record c's balance of the asset before the call by reading address(c).balance is only for Ether; we can't read ERC20 balances here.
        // Instead, observe that withdrawGovernanceAsset uses IERC20(asset).transfer to msg.sender.
        // We cannot read ERC20 balances, so we assert properties about pendingFlashDecision observable entries only.

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (address post_asset, uint256 post_amount, uint256 post_unlockTime, , ) = c.pendingFlashDecision(targetContract, address(this));

        // If call succeeded then the preconditions in C must have held, and post_amount must be zero and post_asset may be cleared.
        // If call reverted then at least one precondition failed.
        assert(
            (!reverted && pre_asset == asset && pre_amount > 0 && pre_unlockTime < block.timestamp && post_amount == 0) ||
            (reverted && (pre_asset != asset || pre_amount == 0 || !(pre_unlockTime < block.timestamp)))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test calling withdrawGovernanceAsset for (targetContract, asset).
    // If the call succeeds, then the preconditions in C must have held and the pending amount is cleared afterwards.
    function run(address targetContract, address asset) public payable {
        require(targetContract != address(0) && asset != address(0));

        // Read the pending entry for this test contract (c.pendingFlashDecision is public and returns the struct FlashGovernanceConfig)
        (uint256 pre_amount, uint256 pre_unlockTime, address pre_asset) = _readPending(targetContract);

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 post_amount, , address post_asset) = _readPending(targetContract);

        // General property:
        // - If the call succeeded (not reverted) then before the call: pre_asset == asset, pre_amount > 0, pre_unlockTime < block.timestamp
        //   and after the call post_amount == 0.
        // - If the call reverted then at least one of those before-call conditions did not hold.
        assert(
            (!reverted && pre_asset == asset && pre_amount > 0 && pre_unlockTime < block.timestamp && post_amount == 0)
            ||
            (reverted && (pre_asset != asset || pre_amount == 0 || !(pre_unlockTime < block.timestamp)))
        );
    }

    // Helper to read the public mapping pendingFlashDecision(target, user) which has type FlashGovernanceConfig
    // The autogenerated getter for mapping(address => mapping(address => FlashGovernanceConfig)) returns
    // (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable) but we only extract the first three by expecting a 3-tuple via this view call.
    function _readPending(address target) internal view returns (uint256 amount, uint256 unlockTime, address asset) {
        (amount, unlockTime, asset, ) = c.pendingFlashDecision(target, address(this));
    }

    receive() external payable {}
}

