contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We model a caller that has previously been accepted as a successful proposal by making
    // the test contract the DAO and using Governable's constructor behavior: the deployed c
    // is fresh and its DAO is set to the provided address. The checker deploys a fresh c
    // with this test as deployer so we can call onlySuccessfulProposal functions.

    // Single public function as required by the harness. We take inputs that will be used
    // to configure flash governance and then assert the contract's public getters match them.
    function run(address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        require(address(this) != address(0)); // trivial precondition to satisfy template

        // Call configureFlashGovernance which is protected by onlySuccessfulProposal.
        // According to Governable, when DAO == address(this) the modifier allows calls from DAO.
        // Since the test contract deployed c, the c.DAO should be address(this) and thus
        // this call should be allowed and succeed for the fresh deployment.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Read back the public struct fields via the autogenerated getter for flashGovernanceConfig
        (uint256 gotAmount, uint256 gotUnlockTime, address gotAsset, bool gotAssetBurnable) = c.flashGovernanceConfig();

        // The single assertion: the public state must equal the inputs we wrote.
        // This is a general property: configureFlashGovernance writes these four fields.
        assert(gotAmount == amount && gotUnlockTime == unlockTime && gotAsset == asset && gotAssetBurnable == assetBurnable);
    }

    receive() external payable {}
}

