contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint as required
    function run(address callerConfigurable, int256 v1, int256 v2, bool enableEnforcement, bool configurableConfigured) public payable {
        // Preconditions about balances are not required; we only call view/set functions.
        // We will: set enforcement flag for callerConfigurable, then call enforceToleranceInt via c as msg.sender
        // But note: when this test calls c.enforceToleranceInt it will be called with msg.sender == address(this)
        // so we use c.setEnforcement to toggle enforcement for address(this).

        // configure enforcement active/disabled for this test contract
        c.setEnforcement(enableEnforcement);

        // We cannot directly set Configurable(configurable).configured()'s return value on arbitrary address.
        // However, enforceTolerance checks: if (!enforceLimitsActive[msg.sender] || !Configurable(msg.sender).configured()) return;
        // So one of the two can disable enforcement. We can only control enforceLimitsActive (above).
        // We'll therefore observe behavior: if enforcement is disabled or caller's configured() is false, call must not revert.

        // Call enforceToleranceInt and catch revert
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable values needed for the assertion
        // We can read whether enforcement is active for this contract via calling setEnforcement and then reading nothing directly;
        // however enforceLimitsActive has public setter only; there's no getter. But effect is observable through whether enforceToleranceInt reverted.
        // We assert a general relation: if enforcement was disabled (enableEnforcement == false) then enforceToleranceInt must NOT revert.
        // Otherwise (enableEnforcement == true) we cannot fully determine Configurable(msg.sender).configured() value, so we assert that either it did not revert or callerConfigured was true/false compatibility:

        // Formulate assertion: if enforcement disabled then not reverted; else (enableEnforcement==true) it's allowed to either revert or not (no constraint).
        assert(!(!enableEnforcement) == reverted ? false : true);
    }

    receive() external payable {}
}

