contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary params
    function run(address targetContract, address asset) public payable {
        // Observe pending before call
        (uint256 before_amount, uint256 before_unlock, address before_asset) = getPending(targetContract, address(this));

        // Attempt the withdraw and capture whether it reverted
        bool reverted;
        // We need to ensure transfer() call inside withdrawGovernanceAsset uses ERC20 on-chain state;
        // but we can't manipulate ERC20 here. The property will allow either revert or successful transfer.
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, read pending entry again
        (uint256 after_amount, uint256 after_unlock, address after_asset) = getPending(targetContract, address(this));

        // If the call did not revert, then it must have satisfied the require in withdrawGovernanceAsset:
        //   pending.asset == asset && pending.amount > 0 && pending.unlockTime < block.timestamp
        // and it must have deleted the pending entry (so amount == 0 afterwards). We assert that either the call reverted,
        // or those three conditions held before the call and after_amount==0.
        assert(
            reverted || (
                before_asset == asset &&
                before_amount > 0 &&
                before_unlock < block.timestamp &&
                // after_amount should be zero after successful withdraw
                after_amount == 0
            )
        );
    }

    // helper to read the pendingFlashDecision mapping via the public getter
    function getPending(address targetContract, address who)
        internal
        view
        returns (uint256 amount, uint256 unlockTime, address asset)
    {
        // The public getter pendingFlashDecision returns the struct (amount, unlockTime, asset, assetBurnable?)
        // But in contract C the struct FlashGovernanceConfig has fields (amount, unlockTime, asset, assetBurnable)
        // The autogenerated getter will return (uint256,uint256,address,bool). We only capture first three.
        (uint256 a, uint256 u, address asst, ) = c.pendingFlashDecision(targetContract, who);
        return (a, u, asst);
    }

    // receive to allow ETH if needed by ERC20s or other interactions
    receive() external payable {}
}

