contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that the checker will call with arbitrary params
    function run(address targetContract, address asset) public payable {
        // Observe pending before call via autogenerated getter: (amount, unlockTime, asset, assetBurnable)
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, ) = c.pendingFlashDecision(targetContract, address(this));

        // Record c balance before to detect transfer out
        uint256 before_c_balance = address(c).balance;
        uint256 before_self_balance = address(this).balance;

        // Attempt the withdraw and capture whether it reverted
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe pending after call
        (uint256 after_amount, , address after_asset, ) = c.pendingFlashDecision(targetContract, address(this));
        uint256 after_c_balance = address(c).balance;
        uint256 after_self_balance = address(this).balance;

        // If the call succeeded then the preconditions in withdrawGovernanceAsset must have held
        // and the pending entry must have been cleared (amount == 0) and the exact amount moved from c to this
        // Otherwise the call reverted.
        assert(
            reverted || (
                before_asset == asset &&
                before_amount > 0 &&
                before_unlockTime < block.timestamp &&
                after_amount == 0 &&
                // ensure c decreased by before_amount and this increased by before_amount
                after_c_balance + before_amount == before_c_balance &&
                after_self_balance == before_self_balance + before_amount
            )
        );
    }

    // allow receiving ETH if transfer happens
    receive() external payable {}
}

