contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint with parameters driving calls
    function run(int256 v1, int256 v2, uint256 uv1, uint256 uv2, bool useInt, address payable callerAsConfigurable) public payable {
        require(true);

        // Read initial observable flags
        bool configuredFlag = c.configured();

        // Ensure this test contract's enforcement flag can be toggled via c.setEnforcement
        // setEnforcement is non-view and will change c's state; call directly
        // We call with 'false' to disable enforcement for msg.sender (this contract) and with 'true' to enable in different branches
        c.setEnforcement(false);
        bool reverted;

        // Make the deciding call: either enforceToleranceInt or enforceTolerance
        // We must catch whether it reverts.
