    // single public test function taking inputs to exercise withdrawGovernanceAsset
    function run(address targetContract, address asset) public payable {
        require(true);

        // Read pending decision values before the call via public getter
        (uint256 before_amount, uint256 before_unlock, , , ) = c.pendingFlashDecision(targetContract, address(this));
        // Also read c's balance of the asset (ERC20 balance) by calling balanceOf on the token contract
        uint256 cBalanceBefore;
        bool tokenHasBalanceOf;
        // Try to read balanceOf; if the token does not implement balanceOf the call will revert, so catch via low-level
        {
            (bool ok, bytes memory ret) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c));
            if (ok && ret.length >= 32) {
                cBalanceBefore = abi.decode(ret, (uint256));
                tokenHasBalanceOf = true;
            } else {
                tokenHasBalanceOf = false;
                cBalanceBefore = 0;
            }
        }

        // Attempt the withdraw and observe whether it reverts
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read pending decision values after the call
        (uint256 after_amount, uint256 after_unlock, , , ) = c.pendingFlashDecision(targetContract, address(this));

        // Read c's balance after (if token supports balanceOf)
        uint256 cBalanceAfter;
        if (tokenHasBalanceOf) {
            (bool ok2, bytes memory ret2) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c));
            if (ok2 && ret2.length >= 32) cBalanceAfter = abi.decode(ret2, (uint256));
            else cBalanceAfter = cBalanceBefore;
        } else {
            cBalanceAfter = cBalanceBefore;
        }

        // General rule:
        // If withdraw succeeded (not reverted) then either before_amount==0 (nothing to transfer) or
        // the token balance of c decreased by before_amount and the pending decision was cleared (after_amount==0),
        // else if it reverted then pending decision must be unchanged (after_amount==before_amount and after_unlock==before_unlock)
        // Note: when token doesn't implement balanceOf we still require that a successful call clears the pending decision.
        if (!reverted) {
            if (tokenHasBalanceOf) {
                assert((before_amount == 0 && after_amount == 0) || (cBalanceAfter + before_amount == cBalanceBefore && after_amount == 0));
            } else {
                assert(after_amount == 0);
            }
        } else {
            assert(after_amount == before_amount && after_unlock == before_unlock);
        }
    }

    receive() external payable {}
}

