    // - targetContract: address under which the pending decision is stored (we will use some target)
    // - asset: the asset address to match the pending entry
    // Notes: The test deployer is the DAO passed into C at construction time; the checker deploys a fresh C.
    function run(address targetContract, address asset) public payable {
        require(true);

        // Observe before values
        // pendingFlashDecision is public getter with signature (amount,unlockTime,asset,assetBurnable?) but in contract it's a mapping to struct with 4 fields.
        // The compiler generates a getter with (address,address) -> (uint256,uint256,address,bool)
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Also observe c's balance of Ether (address balance) -- withdrawGovernanceAsset uses ERC20 transfer, so Ether balance should be unchanged.
        uint256 before_c_balance = address(c).balance;
        uint256 before_self_balance = address(this).balance;

        bool reverted;
        // Call withdrawGovernanceAsset and catch revert
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));
        uint256 after_c_balance = address(c).balance;
        uint256 after_self_balance = address(this).balance;

