contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take targetContract and asset to reference the pending map, and set up a scenario where
    // pendingFlashDecision[targetContract][address(this)] has some amount by first configuring
    // flashGovernanceConfig and then calling assertGovernanceApproved (which requires an ERC20
    // transferFrom). To avoid dealing with real ERC20 tokens, we will not attempt to create a
    // successful pending decision; instead we assert the general relationship between the revert
    // flag of withdrawGovernanceAsset and the post-call pending state and balances. The rule below
    // says: either withdrawGovernanceAsset reverts with the specific message, or it succeeds and
    // transfers the exact pending amount and clears the pending entry.

    // Note: Because interacting with ERC20 tokens and the internal pending mapping setup is
    // environment-dependent, this property is expressed purely in terms of observable public
    // getters: the public pendingFlashDecision getter for (targetContract, address(this)) fields
    // (asset and amount) and the behavior of withdrawGovernanceAsset. We call withdrawGovernanceAsset
    // and check that if it did not revert then the returned prior amount was sent and the pending
    // amount is zero afterward. If it reverted, the revert must be with the documented message.

    receive() external payable {}

    function run(address targetContract, address asset) public payable {
        require(true);

        // Read prior pending entry observable fields
        (address priorAsset, uint256 priorAmount, uint256 priorUnlockTime, , ) = c.pendingFlashDecision(targetContract, address(this));
        uint256 balanceBefore = 0;
        if (asset != address(0)) {
            // try to read token balance if asset is this contract (ERC20 read may revert for non-ERC20)
            // We avoid calling IERC20 here; instead we observe only contract balances and the pending mapping.
        }

        bool reverted;
        // attempt the call and capture revert
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch (bytes memory) {
            reverted = true;
        }

        // After call, read pending entry again
        (address postAsset, uint256 postAmount, uint256 postUnlockTime, , ) = c.pendingFlashDecision(targetContract, address(this));

        // If call reverted, then nothing observable about pending entry is required to have changed
        // by the contract model; however the contract reverts with a specific message when the
        // preconditions are not met: "Limbo: Flashgovernance decision pending." We cannot access the
        // revert string from the catch here, so we require that if it reverted then the preconditions
        // for success were not satisfied (i.e., prior asset mismatch or amount==0 or unlockTime >= now).
        // We assert the disjunction: either it reverted and preconditions were not met, or it succeeded
        // and the pending entry was cleared and (if priorAmount>0) the postAmount is zero.

        bool preconditionsHold = (priorAsset == asset) && (priorAmount > 0) && (priorUnlockTime < block.timestamp);

        // The general rule asserted: withdrawGovernanceAsset can succeed only when preconditionsHold,
        // and when it succeeds, it clears the pending entry (postAmount == 0 and postAsset == address(0) or unchanged asset but amount zero).
        assert( reverted ? (!preconditionsHold) : (preconditionsHold && postAmount == 0) );
    }
}

